import{_ as e,o as t,c as _,a3 as s}from"./chunks/framework.DdpBa4_E.js";const o="/ReadBooks/assets/image-090.BbTxdliu.jpg",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/63-“下流”女性唱唱跳跳.md","filePath":"books/xialiu-shehui/63-“下流”女性唱唱跳跳.md","lastUpdated":1794732511000}'),p={name:"books/xialiu-shehui/63-“下流”女性唱唱跳跳.md"};function i(r,a,l,n,d,c){return t(),_("div",null,[...a[0]||(a[0]=[s('<h2 id="下流-女性唱唱跳跳" tabindex="-1">“下流”女性唱唱跳跳 <a class="header-anchor" href="#下流-女性唱唱跳跳" aria-label="Permalink to &quot;“下流”女性唱唱跳跳&quot;">​</a></h2><p>另一方面，团块次代女性的情况又怎样呢？</p><p>按选择人数的多少为序来看女性的选项，上流阶层女性的兴趣爱好依次是阅读（70.6%）、电脑·互联网（64.7%）、在家看碟片（58.8%）、旅行·休闲（58.8%）、外出吃饭·品尝美食（58.8%）。</p><p>中流阶层女性感兴趣的事情依次是电脑·互联网（71.2%）、阅读（67.3%）、旅行·休闲（59.6%）、外出吃饭·品尝美食（59.6%）、购物（55.8%）。</p><p>接着来看下流阶层，其兴趣选项依次为电脑·互联网（67.7%）、阅读（54.8%）、在家看碟片（54.8%）、外出吃饭·品尝美食（54.8%）、旅行·休闲（48.4%）、购物（48.4%）。</p><p>如果按不同的阶层意识来进行比较，可以看出阶层越往“上”，选择阅读、园艺、音乐欣赏、烹饪等的人越多，这些女性选择的大多是比较传统的专职家庭主妇的选项（见表6-2）。</p><p>表6-2　团块次代不同阶层意识女性的兴趣差别（主要选项）</p><p><img src="'+o+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、e-FALCON共同实施的“欲求调查”</p><p>另一方面，阶层越往“下”，选择音乐欣赏的人越多，这一点倒是跟男性不谋而合，此外选择乐器演奏的女性也很多。需要指出的是，虽然所占比例不高，但对绘画、插画制作、跳舞等亚文化项目感兴趣的女性也很多。换句话说，就是她们中有不少人喜欢唱唱跳跳或是绘画。这种倾向也正好印证了先前苅谷刚彦教授的说法：阶层越往“下”，越是在亚文化的兴趣方面有“自我主张”。</p>',10)])])}const m=e(p,[["render",i]]);export{h as __pageData,m as default};
